export function copy(button,env){const clipboard=env.clipboard;const fetchText=env.fetchText;const url=button.dataset.markdown;if(clipboard===undefined||fetchText===undefined||url===undefined||url==="")return Promise.resolve();return fetchText(url).then((markdown)=>clipboard.writeText(markdown),).then(()=>{env.status.textContent=button.dataset.copied??"";},()=>{env.status.textContent=button.dataset.copyFailed??"";},);}
export function activate(button,env){if(env.clipboard===undefined||env.fetchText===undefined)return;if(button.dataset.markdown===undefined||button.dataset.markdown==="")return;button.hidden=false;button.addEventListener("click",()=>{void copy(button,env);});}
const globals=globalThis;function browserFetch(url){const fetch=globals.fetch;if(fetch===undefined)return Promise.reject(new Error("fetch is unavailable"));return fetch(url).then((response)=>response.ok?response.text():Promise.reject(new Error(`HTTP ${response.status}`)),);}
if(globals.document!==undefined){const button=globals.document.querySelector("[data-page-agent-copy]");const status=globals.document.querySelector("[data-page-agent-status]");if(button!==null&&status!==null){activate(button,{clipboard:globals.navigator?.clipboard,fetchText:browserFetch,status:status,});}}